  Future<void> _loadUser()async{final b=GetStorage();customerName=_first([b.read('name'),b.read('fullName'),b.read('userName'),b.read('customerName')]);customerPhone=_first([b.read('phone'),b.read('userPhone'),b.read('customerPhone'),b.read('mobile')]);final saved=_first([b.read('deliveryZoneId')]);if(DeliveryZoneService.zones.any((z)=>z.id==saved))customerZoneId=saved;nameController.text=customerName;phoneController.text=customerPhone;areaController.text=_first([b.read('deliveryAreaDetails')]);streetController.text=_first([b.read('deliveryStreet')]);buildingController.text=_first([b.read('deliveryBuilding')]);floorController.text=_first([b.read('deliveryFloor')]);apartmentController.text=_first([b.read('deliveryApartment')]);landmarkController.text=_first([b.read('deliveryLandmark')]);if(mounted)setState(()=>loadingUser=false);if(customerZoneId!=null)await _refreshQuote();}
