  Future<void> _placeOrder(List<Map<String,dynamic>> items)async{if(items.isEmpty||placingOrder)return;final name=nameController.text.trim().isNotEmpty?nameController.text.trim():customerName,phone=phoneController.text.trim().isNotEmpty?phoneController.text.trim():customerPhone;if(phone.isEmpty)return _message('اكتب رقم الهاتف');if(customerZoneId==null)return _message('حدد نطاق عنوان التوصيل');if(areaController.text.trim().isEmpty)return _message('اكتب اسم الحي أو القرية');if(streetController.text.trim().isEmpty)return _message('اكتب اسم الشارع أو الطريق');if(CartManager.storeId.trim().isEmpty)return _message('تعذر تحديد المتجر');if(loadingQuote)return _message('جاري حساب رسوم التوصيل');setState(()=>placingOrder=true);try{final quote=deliveryQuote??await DeliveryZoneService.quote(storeId:CartManager.storeId,customerZoneId:customerZoneId!);final box=GetStorage();await box.write('name',name);await box.write('phone',phone);await box.write('deliveryZoneId',customerZoneId);await box.write('deliveryAreaDetails',areaController.text.trim());await box.write('deliveryStreet',streetController.text.trim());await box.write('deliveryBuilding',buildingController.text.trim());await box.write('deliveryFloor',floorController.text.trim());await box.write('deliveryApartment',apartmentController.text.trim());await box.write('deliveryLandmark',landmarkController.text.trim());final subtotal=_subtotal(items);final r=FirebaseDatabase.instance.ref('orders').push();final fullAddress=[areaController.text.trim(),streetController.text.trim(),if(buildingController.text.trim().isNotEmpty)'منزل/عمارة ${buildingController.text.trim()}',if(floorController.text.trim().isNotEmpty)'الدور ${floorController.text.trim()}',if(apartmentController.text.trim().isNotEmpty)'شقة ${apartmentController.text.trim()}',if(landmarkController.text.trim().isNotEmpty)'علامة مميزة: ${landmarkController.text.trim()}'].join(' - ');await r.set({'id':r.key,'storeId':CartManager.storeId,'storeName':CartManager.storeName,'storeT