class _SmartImage extends StatelessWidget{final String image;const _SmartImage({required this.image});@override Widget build(BuildContext context){final v=image.trim();if(v.isEmpty)return _fallback();if(v.startsWith('data:image')){try{return Image.memory(base64Decode(v.split(',').last),fit:BoxFit.cover,width:double.infinity,height:double.infinity);}catch(_){return _fallback();}}if(!v.startsWith('http')){try{return Image.memory(base64Decode(v),fit:BoxFit.cover,width:double.infinity,height:double.infinity);}catch(_){return _fallback();}}return Image.network(v,fit:BoxFit.cover,width:double.infinity,height:double.infinity,errorBuilder:(_,__,___)=>_fallback());}Widget _fallback()=>Container(color:AppColors.primaryLight,alignment:Alignment.center,child:const Icon(Icons.fastfood_outlined,color:AppColors.primary));}
